typedef unsigned int u_int;
#define FALSE 0
#define TRUE 1

struct sceIpuDmaEnv {
    u_int d4madr;
    u_int d4tadr;
    u_int d4qwc;
    u_int d4chcr;
    u_int d3madr;
    u_int d3qwc;
    u_int d3chcr;
    u_int ipubp;
    u_int ipuctrl;
};

struct ViBuf {
    void *data;
    void *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
};

extern "C" int WaitSema(int sema);
extern "C" int SignalSema(int sema);
extern void setD4_CHCR(u_int val);
extern void setD3_CHCR(u_int val);
__asm__(".equ WaitSema, 0x003DB6A0");
__asm__(".equ SignalSema, 0x003DB680");
__asm__(".equ setD4_CHCR__FUi, 0x00389E68");
__asm__(".equ setD3_CHCR__FUi, 0x00389DF8");

#define D4_CHCR ((volatile u_int*)0x1000B400)
#define D4_MADR ((volatile u_int*)0x1000B410)
#define D4_QWC ((volatile u_int*)0x1000B420)
#define D4_TADR ((volatile u_int*)0x1000B430)
#define D3_CHCR ((volatile u_int*)0x1000B000)
#define D3_MADR ((volatile u_int*)0x1000B010)
#define D3_QWC ((volatile u_int*)0x1000B020)
#define DGET_IPU_BP() (*(volatile u_int*)0x10002020)
#define DGET_IPU_CTRL() (*(volatile u_int*)0x10002010)

static int viBufStopDMA( ViBuf* f )
{
    WaitSema( f->sema );
    f->isActive = FALSE;
    setD4_CHCR( (0<<8) | (1<<2) | 1 );
    f->env.d4madr = *D4_MADR;
    f->env.d4tadr = *D4_TADR;
    f->env.d4qwc =  *D4_QWC;
    f->env.d4chcr = *D4_CHCR;
    while( DGET_IPU_CTRL() & 0xf0 )
        ;
    setD3_CHCR( (0<<8) | 0 );
    f->env.d3madr = *D3_MADR;
    f->env.d3qwc =  *D3_QWC;
    f->env.d3chcr = *D3_CHCR;
    f->env.ipubp = DGET_IPU_BP();
    f->env.ipuctrl = DGET_IPU_CTRL();
    SignalSema(f->sema);
    return TRUE;
}
__asm__(".globl viBufStopDMA__FP5ViBuf");
